window.CONTENT_OVERLAYS = window.CONTENT_OVERLAYS || {};
window.CONTENT_OVERLAYS["en"] = {"levels":{"A1":"Level 1 · Débutant","A2":"Level 2 · Élémentaire"},"modules":{"A1-m1":"First contacts","A1-m2":"Daily routine","A1-m3":"City and identity","A1-m4":"Getting around and taking care of yourself","A1-m5":"Describing the world around you","A1-m6":"Leisure and the past"},"levelTests":{"A1-final":"A1 Level Test"},"units":{"A1-1":{"title":"Greeting and saying goodbye","goal":"Greet someone, say goodbye and say thank you in a basic interaction.","lessons":{"ola-e-tchau":"Saying hello and goodbye","informal-agradecer":"Greeting informally and saying thank you","cortesia-e-como-vai":"Saying please and asking how someone is","checkpoint":"Checkpoint"},"vocab":["hi, hello / good morning","good evening (greeting)","goodbye","hi / bye (informal)","thank you / thanks","you're welcome","please (formal)","sorry / excuse me","all good? / all good.","see you soon"],"phrases":[{"t":"Hello! My name is Brune.","scenario":"You meet someone new at a party and want to introduce yourself. What do you say?"},{"t":"Thank you very much!","scenario":"A friend helps you carry your groceries. How do you thank them?"},{"t":"Sorry, I don't understand.","scenario":"Someone is speaking French very fast and you didn't understand a thing. What do you say?"},{"t":"I'm doing well, and you?","scenario":"A friend asks \"Ça va ?\". You want to say you're fine and ask back. What do you say?"},{"t":"Good evening! How are you? (formal)"},{"t":"Goodbye, see you tomorrow!"},{"t":"Hi! Are you doing well?"},{"t":"You're welcome, it's nothing."},{"t":"A coffee, please."}],"dialogue":{"title":"Meeting on the street","lines":["Hello!","Hello! How are you?","I'm doing well, thanks! And you?","I'm fine. See you soon!"]},"concepts":{"bonjour-vs-bonsoir":[{"title":"\"Bonjour\" or \"Bonsoir\"?","body":"We use <strong>bonjour</strong> from morning until late afternoon — it's the standard greeting of the day. In the evening, when arriving somewhere, we switch to <strong>bonsoir</strong>. <strong>Salut</strong>, on the other hand, works at any time of day, but only with friends or people you're close to — never with strangers or in formal settings.","examples":["hi, hello / good morning","good evening (greeting)"]}],"svp-informal":[{"title":"\"S'il vous plaît\" in everyday life","body":"In casual speech or text messages, <strong>s'il vous plaît</strong> almost always gets shorter: with friends it becomes <strong>s'il te plaît</strong> (the \"tu\" form — the informal \"you\" — not \"vous\", the polite or plural \"you\"), and in writing you'll often see just <strong>STP</strong>. The full \"vous\" form is still the safest choice with strangers.","examples":["please (informal, among friends)","text abbreviation for \"s'il te plaît\""]}],"a-bientot-informal":[{"title":"Among friends, \"à bientôt\" becomes \"à plus\"","body":"With friends, <strong>à bientôt</strong> is common, but in everyday speech (and almost always in text messages) the most common goodbye is <strong>à plus</strong> — and in writing it usually becomes just <strong>A+</strong>. With strangers or in formal settings, \"à bientôt\" is still the right choice.","examples":["see you later / later (informal)","text abbreviation for \"à plus\""]}],"la-bise-cumprimento":[{"title":"Why do French people greet each other with kisses on the cheek?","body":"Besides saying \"bonjour\", it's very common to greet friends and family with <strong>la bise</strong> — one or more light kisses on the cheek (the number varies by region: 2 is the most common, but in some regions it's 3 or even 4!). With strangers or in formal/professional settings, people shake hands instead.","examples":["to greet with a kiss (or kisses) on the cheek"]}]},"trueFalse":[{"claim":"This is what we say when someone helps us a lot.","whyNote":"Correct — <strong>merci beaucoup</strong> means \"thank you very much\"; it's exactly what you say to thank someone for their help."}]},"A1-10":{"title":"Shopping","goal":"Ask prices (with numbers up to one hundred), try on clothes and buy in a store.","lessons":{"roupas-e-preco":"Pants, dress and expensive","tamanho-e-loja":"Cheap, size and store","numeros-30-50":"Numbers: thirty to fifty","numeros-60-80":"Numbers: sixty to eighty","numeros-90-100":"Numbers: ninety and one hundred","checkpoint":"Checkpoint"},"vocab":["the pants","the dress","expensive","cheap / inexpensive","the size","the store","thirty","forty","fifty","sixty","seventy","eighty","ninety","one hundred"],"phrases":[{"t":"How much is this?","scenario":"You're in a store and want to know the price of a product. What do you ask?"},{"t":"It costs forty euros.","scenario":"A customer asks the price of a product that costs forty euros. What do you answer?"},{"t":"Can I try on these pants?","scenario":"You're in a clothing store and want to try on pants before buying. What do you ask?"},{"t":"That's one hundred euros, please.","scenario":"You're the salesperson and need to charge the customer one hundred euros. What do you say?"},{"t":"The pants are too big."},{"t":"The dress is very pretty."},{"t":"It's not expensive at all."},{"t":"The size is too small."},{"t":"The store closes at 7 p.m."},{"t":"This jacket costs thirty euros."},{"t":"These shoes cost fifty euros."},{"t":"The coat costs seventy euros."},{"t":"This dress costs eighty euros."},{"t":"This bag costs ninety euros."}],"dialogue":{"title":"In a store","lines":["Hello, I'm looking for a dress.","What size are you?","I'm a 38. How much is it?","It costs sixty euros.","Perfect, I'll take it!"]},"concepts":{"voudrais-vs-peux":[{"title":"\"Je voudrais\" or \"je peux\"?","body":"<strong>Je voudrais</strong> (I would like) is the politest way to ask for something in a store — it sounds kinder than \"je veux\" (I want). <strong>Je peux...?</strong> (Can I...?) is used to ask permission, like trying on clothes: <strong>je peux</strong> essayer ce pantalon? Both are polite, but they serve different moments: asking for something vs. asking permission.","examples":[]}],"combien-ca-coute-wh-in-situ":[{"title":"\"Combien ça coûte ?\" also becomes \"Ça coûte combien ?\"","body":"Notice that the dialogue you just read already uses the everyday form: <strong>Ça coûte combien ?</strong> instead of \"Combien ça coûte ?\". In everyday speech, it's common to move the question word to the end of the sentence. In the exercises here, keep using \"Combien ça coûte ?\" — it's the form the exercises ask for.","examples":["how much is it? (everyday speech)"]}]},"trueFalse":[]},"A1-11":{"title":"Grocery shopping","goal":"Make a shopping list and say what you eat or don't eat in everyday life.","lessons":{"carne-frango-legumes":"Meat, chicken and vegetables","salada-arroz-massa":"Salad, rice and pasta","acucar-sal-ovo-sobremesa":"Sugar, salt, egg and dessert","checkpoint":"Checkpoint"},"vocab":["the meat","the chicken","the vegetables","the salad","the rice","the pasta","the sugar","the salt","the egg","the dessert"],"phrases":[{"t":"I like meat.","scenario":"Someone asks if you like meat, and you like it a lot. What do you answer?"},{"t":"I eat vegetables every day.","scenario":"Someone asks about your eating habits and you eat vegetables every day. What do you say?"},{"t":"I don't eat meat.","scenario":"You're a vegetarian and need to tell the waiter you don't eat meat. What do you say?"},{"t":"I'll take rice and pasta.","scenario":"At the supermarket, someone asks what you're going to get. What do you answer?"},{"t":"The chicken is delicious tonight."},{"t":"Vegetables are good for your health."},{"t":"The salad is fresh."},{"t":"Rice and pasta are my favorite dishes."},{"t":"The sugar and the salt are on the table."},{"t":"The egg is cooked."},{"t":"The dessert is ready."}],"dialogue":{"title":"Making the shopping list","lines":["What are we buying?","Rice, vegetables and chicken.","Do you want a dessert?","Yes, with sugar, please!"]},"concepts":{"negation-partitif":[{"title":"\"Je ne mange pas DE viande\" — where did the \"la\" go?","body":"After a negation with <strong>ne... pas</strong>, the articles du/de la/des disappear and become just <strong>de</strong> (or <strong>d'</strong> before a vowel): je mange <strong>de la</strong> viande → je ne mange <strong>pas de</strong> viande. This rule applies to almost every negation of quantity in French — it's worth paying attention to it.","examples":["the meat"]}],"le-marche-tradicao":[{"title":"Beyond the supermarket: the marché","body":"In many French cities and villages, besides the supermarket, it's a tradition to shop at the <strong>marché</strong> — an open-air market that usually takes place once or twice a week, with stalls of local producers selling fresh fruit, vegetables, cheese, meat and bread. It's also a social moment: many people run into neighbors and acquaintances there.","examples":["the market / the open-air market"]}]},"trueFalse":[]},"A1-12":{"title":"Weights and quantities","goal":"Ask for specific amounts when shopping: kilo, litre, a little, a lot...","lessons":{"quilo-meio-quilo-litro":"Kilo, half a kilo and litre","grama-pouco-muito":"Gram, a little and a lot","suficiente-demais-fatia-garrafa":"Enough, too much, slice and bottle","checkpoint":"Checkpoint"},"vocab":["a kilo (of)","half a kilo","a litre","a gram","a little (of)","a lot (of) / plenty (of)","enough (of)","too much (of) / too many (of)","a slice (of)","a bottle (of)"],"phrases":[{"t":"I'll take a kilo of apples.","scenario":"You're at the market and want to buy a kilo of apples. What do you say to the seller?"},{"t":"A litre of milk, please.","scenario":"You're at the shop and want to ask for a litre of milk. What do you say?"},{"t":"That's too much sugar for me.","scenario":"Someone is serving you coffee with a lot of sugar, and it's too much for you. What do you say?"},{"t":"A slice of bread, please.","scenario":"At the breakfast table, you want to ask for a slice of bread. What do you say?"},{"t":"One gram is very little."},{"t":"There are a lot of people here."},{"t":"I don't have enough time."}],"dialogue":{"title":"Shopping at the market","lines":["How many apples would you like?","Half a kilo, please.","Anything else?","A bottle of water and a little cheese."]},"concepts":{"de-quantite":[{"title":"\"Un kilo DE pommes\" — the same \"de\" rule","body":"After an expression of quantity (un kilo <strong>de</strong>, un litre <strong>de</strong>, beaucoup <strong>de</strong>, trop <strong>de</strong>), the article also disappears and becomes just <strong>de</strong>/<strong>d'</strong> — the same thing that happens after a negation (previous unit). Notice: you don't say \"un kilo des pommes\", you say <strong>un kilo de pommes</strong>.","examples":["a kilo (of)"]}]},"trueFalse":[]},"A1-13":{"title":"Weather and seasons","goal":"Talk about the weather and the seasons of the year.","lessons":{"tempo-bonito-frio-quente":"Describing the weather: nice, cold and hot","chuva-neve-sol":"Rain, snow and sun","estacoes-do-ano":"The four seasons","checkpoint":"Checkpoint"},"vocab":["the weather is nice","it's cold","it's hot","it's raining","it's snowing","the sun","spring","summer","autumn / fall","winter"],"phrases":[{"t":"What's the weather like?","scenario":"You're about to go out and want to know what the weather is like outside. What do you ask?"},{"t":"It's very hot today.","scenario":"Someone asks what the weather is like, and today it's very hot. What do you answer?"},{"t":"I like winter.","scenario":"Someone asks your favorite season, and it's winter. What do you say?"},{"t":"It often rains in autumn.","scenario":"Someone asks what autumn is like in your city, with frequent rain. What do you say?"},{"t":"It snows a lot in winter."},{"t":"The sun is shining today."},{"t":"Spring is my favorite season."},{"t":"Autumn is very colorful."}],"dialogue":{"title":"Talking about the weather","lines":["What's the weather like today?","It's nice, but it's cold.","Which season do you prefer?","I prefer summer, it's hot."]},"concepts":{"il-fait-vs-jai":[{"title":"\"Il fait chaud\" or \"j'ai chaud\"?","body":"To talk about the <strong>weather</strong>, French uses the verb faire: <strong>il fait chaud</strong> (it's hot outside). To talk about a <strong>feeling of your own</strong>, it uses avoir: <strong>j'ai chaud</strong> (I'm hot, I feel hot). They're similar sentences but with very different subjects — impersonal \"il\" for the weather, \"je\" for yourself.","examples":["it's hot"]}]},"trueFalse":[{"claim":"This sentence describes how a person is feeling.","whyNote":"Wrong — <strong>il fait chaud</strong> describes the WEATHER (it's hot), not how someone feels. The \"il\" here is impersonal, as in \"it's hot out.\""}]},"A1-14":{"title":"Transport","goal":"Take public transport and buy a ticket.","lessons":{"onibus-trem-metro":"Bus, train and metro","carro-bicicleta-pe":"Car, bicycle and on foot","pegar-transporte-passagem":"Taking transport, stop, ticket and station","checkpoint":"Checkpoint"},"vocab":["the bus","the train","the metro / subway","the car","the bicycle","on foot","to take (a transport)","the stop (bus stop)","the ticket","the station (metro station)"],"phrases":[{"t":"I take the metro every day.","scenario":"Someone asks how you get to work, and it's always by metro. What do you answer?"},{"t":"Where is the bus stop?","scenario":"You're lost and need to find the bus stop. What do you ask?"},{"t":"A ticket, please.","scenario":"You're at the station and want to buy a ticket. What do you say?"},{"t":"I walk to work.","scenario":"Someone asks how you get to work, and you walk. What do you answer?"},{"t":"I'm going to take the bus this morning."},{"t":"The train leaves at eight o'clock."},{"t":"The car is parked in front of the house."},{"t":"The bicycle is faster in the city."},{"t":"The station is closed today."}],"dialogue":{"title":"At the metro station","lines":["Excuse me, does this train go downtown?","Yes, it's the right direction.","How much is the ticket?","It costs two euros."]},"concepts":{"en-vs-a-transport":[{"title":"\"En métro\" or \"à pied\"?","body":"\"Closed\" means of transport (ones you get inside) use <strong>en</strong>: <strong>en</strong> métro, <strong>en</strong> voiture, <strong>en</strong> bus. \"Open\" ways of getting around, where you don't get inside anything — like walking or riding a bike by sitting on top of it — use <strong>à</strong>: <strong>à</strong> pied, <strong>à</strong> vélo. It's a small rule, but it comes up all the time in everyday life.","examples":["the metro / subway","on foot"]}],"metro-paris-historia":[{"title":"The Paris metro was born at a world's fair","body":"The Paris metro opened in <strong>1900</strong>, just in time for that year's World's Fair — a huge event that brought millions of visitors to the city. It's one of the oldest metros in the world, and many stations still keep the original cast-iron Art Nouveau entrance designed by Hector Guimard.","examples":["the metro / subway"]}]},"trueFalse":[]},"A1-15":{"title":"Body and health","goal":"Describe simple symptoms and go to the doctor.","lessons":{"cabeca-barriga-mao":"Head, stomach and hand","pe-doente-medico":"Foot, being sick and the doctor","farmacia-dor-febre":"Pharmacy, pain, fever and feeling","checkpoint":"Checkpoint"},"vocab":["the head","the belly / stomach","the hand","the foot","sick / ill","the doctor","the pharmacy","to be in pain / to hurt","the fever","to feel"],"phrases":[{"t":"I have a headache.","scenario":"You're not feeling well, with a headache. What do you tell a friend?"},{"t":"I feel sick.","scenario":"You're not well and need to let someone know you're sick. What do you say?"},{"t":"Where is the pharmacy?","scenario":"You need to buy medicine and don't know where the pharmacy is. What do you ask?"},{"t":"He has a fever.","scenario":"Your son has a fever and you're explaining it to the doctor. What do you say?"},{"t":"My stomach hurts."},{"t":"The hand is injured."},{"t":"My foot hurts too."},{"t":"The doctor is arriving in ten minutes."},{"t":"I'm going to have a headache if this continues."},{"t":"He's not going to feel well tomorrow."}],"dialogue":{"title":"At the doctor's","lines":["What's wrong?","I have a stomachache and a fever.","Since when?","Since last night.","You need to rest."]},"concepts":{"avoir-mal-vs-etre-malade":[{"title":"\"J'ai mal à la tête\" or \"je suis malade\"?","body":"For pain in a specific part of the body, use <strong>avoir mal à</strong>: <strong>j'ai mal à la</strong> tête (I have a headache). For a general state of feeling unwell, without pointing to a specific part, use <strong>être malade</strong>: <strong>je suis malade</strong> (I'm sick). The choice of verb changes depending on whether you're describing a specific pain or a general state.","examples":["the head","sick / ill"]}],"quest-ce-qui-ne-va-pas-ca-va-pas":[{"title":"\"Qu'est-ce qui ne va pas ?\" in everyday speech becomes \"Ça va pas ?\"","body":"The full question that opens the dialogue, <strong>Qu'est-ce qui ne va pas ?</strong>, tends to shrink a lot in everyday speech: <strong>Ça va pas ?</strong> (literally \"it's not going well?\") asks the same thing in a much shorter, more casual way — similar to \"you OK?\" in English.","examples":["what's wrong? / you OK? (everyday speech)"]}]},"trueFalse":[{"claim":"This sentence is used when someone has a headache.","whyNote":"Correct — <strong>j'ai mal à la tête</strong> literally means \"I have pain at the head\", that is, a headache."}]},"A1-16":{"title":"Colors and descriptions","goal":"Describe colors, objects and people's characteristics.","lessons":{"vermelho-azul-verde":"Red, blue and green","amarelo-preto-branco":"Yellow, black and white","tamanho-e-personalidade":"Describing size and personality","checkpoint":"Checkpoint"},"vocab":["red","blue","green","yellow","black","white","big / tall","small / short","pretty","kind / nice"],"phrases":[{"t":"I like the color blue.","scenario":"Someone asks your favorite color, which is blue. What do you say?"},{"t":"She is very kind.","scenario":"Someone asks what your new colleague is like, and she is very kind. What do you say?"},{"t":"My cat is black and white.","scenario":"Someone asks what your cat looks like, and it's black and white. What do you answer?"},{"t":"It's a pretty red dress.","scenario":"You're describing a pretty red dress you saw in a shop. What do you say?"},{"t":"The sweater is green and yellow."},{"t":"The dog is small."}],"dialogue":{"title":"Describing someone","lines":["What's your brother like?","He's tall and has black hair.","Is he nice?","Yes, he's very kind!"]},"concepts":{"adjective-placement":[{"title":"Why \"une jolie robe rouge\" and not \"une rouge jolie robe\"?","body":"Most adjectives in French come <strong>after</strong> the noun (une robe <strong>rouge</strong>, un chat <strong>noir</strong>) — unlike English, where adjectives come before the noun. Only a small group of common, short adjectives (like jolie, grand, petit, bon) come <strong>before</strong>: une <strong>jolie</strong> robe. That's why \"a pretty red dress\" is <strong>une jolie robe rouge</strong> — jolie before, rouge after.","examples":["red","pretty"]}],"gentil-sympa":[{"title":"In everyday speech, \"gentil\" often becomes \"sympa\"","body":"Notice that the dialogue you just read already uses <strong>sympa</strong> (\"Il est sympa ?\") — a very common short form of <strong>sympathique</strong>, used all the time instead of <strong>gentil</strong> to say someone is nice / a good person.","examples":["nice / a good guy (informal)"]}],"bandeira-tricolor-historia":[{"title":"Bleu, blanc, rouge — the origin of the French flag","body":"The 3 colors you just learned are those of the French flag: <strong>bleu</strong> and <strong>rouge</strong> were the colors of Paris, and <strong>blanc</strong> was the traditional color of the monarchy — the flag, created during the French Revolution, combines the two.","examples":["the flag"]}]},"trueFalse":[]},"A1-17":{"title":"The house and its rooms","goal":"Describe a house and say what there is (and isn't) in it.","lessons":{"casa-apartamento-quarto":"House, apartment and bedroom","cozinha-banheiro-sala":"Kitchen, bathroom and living room","porta-janela-tem-nao-tem":"Door, window and saying what there is or isn't","checkpoint":"Checkpoint"},"vocab":["the house","the apartment","the bedroom","the kitchen","the bathroom","the living room","the door","the window","there is / there are","there isn't / there aren't any"],"phrases":[{"t":"There is a bedroom.","scenario":"Someone asks how many bedrooms your small apartment has, and it has only one. What do you say?"},{"t":"There are two bathrooms.","scenario":"You're describing your house, which has two bathrooms. What do you say?"},{"t":"There isn't a garden.","scenario":"Someone asks if your apartment has a garden, and it doesn't. What do you answer?"},{"t":"It's a big house.","scenario":"You're describing your parents' new house, which is quite big. What do you say?"},{"t":"The house is very big."},{"t":"The apartment has two bedrooms."},{"t":"The bedroom is on the first floor."},{"t":"The kitchen is very clean."},{"t":"The bathroom is next to the bedroom."},{"t":"The living room is comfortable."},{"t":"The door is locked."},{"t":"The window looks out onto the garden."}],"dialogue":{"title":"Viewing an apartment","lines":["How many bedrooms are there?","There are two bedrooms and a kitchen.","Is there a balcony?","No, there isn't a balcony, but there's a nice living room."]},"concepts":{"il-y-a-vs-negation":[{"title":"\"Il y a\" or \"il n'y a pas de\"?","body":"<strong>Il y a</strong> (there is / there are) introduces something that exists: il y a <strong>une</strong> chambre (there is a bedroom). In the negative, the article becomes <strong>de</strong>, just like in the \"food\" and \"quantities\" units: il n'y a <strong>pas de</strong> jardin (there isn't a garden) — never \"il n'y a pas un jardin\".","examples":["there is / there are","there isn't / there aren't any"]}],"il-y-a-ya":[{"title":"In everyday speech, \"il y a\" becomes \"y'a\"","body":"In fast speech, the \"il\" in <strong>il y a</strong> almost disappears — only <strong>y'a</strong> is left: \"y'a une chambre\", \"y'a pas de jardin\". It's so common that it even shows up in informal written messages. In the exercises here, keep writing the full \"il y a\" — it's the form the exercises ask for.","examples":["there's a bedroom (everyday speech)"]}],"andar-terreo-premier-etage":[{"title":"\"1er étage\" is not the ground floor","body":"In France, the ground floor has its own name: <strong>le rez-de-chaussée</strong>. The counting only starts after it — <strong>le premier étage</strong> is what, in the US, we would call the \"second floor\" (one floor above the ground floor). It's worth paying attention to this when looking for an address or taking the elevator.","examples":["the ground floor","the 1st floor (above the ground floor)"]}]},"trueFalse":[]},"A1-18":{"title":"Where things are","goal":"Describe the position of furniture and objects using prepositions of place.","lessons":{"cama-mesa-cadeira":"Bed, table and chair","sofa-luminaria-em-cima":"Sofa, lamp and on top of","embaixo-frente-atras-lado":"Under, in front of, behind and next to","checkpoint":"Checkpoint"},"vocab":["the bed","the table","the chair","the sofa","the lamp","on / on top of","under","in front of","behind","next to"],"phrases":[{"t":"The bed is next to the window.","scenario":"You're describing your bedroom and where the bed is, next to the window. What do you say?"},{"t":"There is a lamp on the table.","scenario":"Someone asks what's on the table — a lamp. What do you answer?"},{"t":"The cat is under the sofa.","scenario":"You're looking for the cat and find it under the sofa. What do you say?"},{"t":"The blue chair is in front of the table.","scenario":"You're explaining where the blue chair is, in front of the table. What do you say?"},{"t":"The cat is behind the chair."}],"dialogue":{"title":"Tidying the bedroom","lines":["Where is my backpack?","It's under the bed.","And my keys?","They're on the table, next to the lamp."]},"concepts":{"sur-vs-dans":[{"title":"\"Sur\" or \"dans\"?","body":"<strong>Sur</strong> means \"on top of\", a surface: il y a une lampe <strong>sur</strong> la table. <strong>Dans</strong> means \"inside\", an enclosed space: il y a des vêtements <strong>dans</strong> l'armoire. The two are often confused by speakers of Portuguese, since we sometimes use \"em\" for both situations.","examples":["on top of"]}]},"trueFalse":[]},"A1-19":{"title":"Leisure and activities","goal":"Talk about hobbies and make weekend plans.","lessons":{"cinema-musica-esporte":"Movies, music and sports","ler-jogar-dancar":"Reading, playing and dancing","cantar-fim-de-semana-sair-filme":"Singing, the weekend, going out and the movie","checkpoint":"Checkpoint"},"vocab":["the movies / the cinema","music","sport / sports","to read","to play (a game) / to play (an instrument)","to dance","to sing","the weekend","to go out","the movie / the film"],"phrases":[{"t":"What do you do on the weekend?","scenario":"You want to know what a friend usually does on weekends. What do you ask?"},{"t":"I like reading books.","scenario":"Someone asks what your favorite hobby is, and it's reading books. What do you say?"},{"t":"Shall we go to the movies tonight?","scenario":"You want to invite a friend to the movies tonight. What do you ask?"},{"t":"He plays the guitar.","scenario":"Someone asks what your brother can do — he plays the guitar. What do you answer?"},{"t":"The movie theater is closed tonight."},{"t":"I love listening to music."},{"t":"Sports are good for your health."},{"t":"Children like to play outside."},{"t":"She loves dancing and singing."},{"t":"We're going out on Saturday night."},{"t":"The movie starts at eight o'clock."}],"dialogue":{"title":"The weekend","lines":["Do you have any plans for the weekend?","Yes, I'm going to the movies with friends.","Which movie are you going to see?","We don't know yet!"]},"concepts":{"jouer-de-vs-jouer-a":[{"title":"\"Jouer DE la guitare\" or \"jouer AU foot\"?","body":"For musical instruments, use <strong>jouer de</strong>: jouer <strong>de la</strong> guitare, jouer <strong>du</strong> piano. For sports and games, use <strong>jouer à</strong>: jouer <strong>au</strong> foot, jouer <strong>aux</strong> cartes. It's a simple little rule, but without it you can mix everything up — worth memorizing this pair of prepositions.","examples":["to play (a game) / to play (an instrument)"]}],"cinema-nasceu-na-franca":[{"title":"Cinema was born in France","body":"In 1895, the brothers <strong>Auguste and Louis Lumière</strong> held in Paris the first public, paid screening of films in history, using the cinematograph they had invented themselves. That's why France is considered the birthplace of cinema — and it still has a highly valued film scene today, with the Cannes Film Festival among the most important in the world.","examples":["the movies / the cinema"]}],"ne-drop-on-sait-pas":[{"title":"In everyday speech, \"On ne sait pas encore !\" loses its \"ne\"","body":"In everyday speech, the <strong>ne</strong> of the negation almost always disappears — <strong>on sait pas encore</strong> instead of \"on ne sait pas encore\". It's probably the most common simplification in all of spoken French, and it applies to any \"ne... pas\" negation. In the exercises here, keep writing the \"ne\" — it's the form the exercises ask for.","examples":["we don't know yet (everyday speech)"]}]},"trueFalse":[{"claim":"This is a way of inviting someone out.","whyNote":"Correct — <strong>on va...?</strong> is a casual way of suggesting plans, like \"shall we go to the movies tonight?\"."}]},"A1-2":{"title":"Introducing yourself","goal":"Say your name and nationality, and ask the other person the same.","lessons":{"pronomes-e-nome":"I, you and saying your name","nome-e-ser":"Your name and the verb être","nacionalidades":"Talking about nationality and country","checkpoint":"Checkpoint"},"vocab":["I","you (informal)","to be called","name","to be","France","Brazil","French (m. / f.)","Brazilian (m. / f.)","country"],"phrases":[{"t":"What's your name?","scenario":"You meet someone new and want to know their name. What do you ask?"},{"t":"I'm Brazilian.","scenario":"Someone asks where you're from. You want to say you're Brazilian. What do you say?"},{"t":"What country are you from?","scenario":"You want to know which country a new person comes from. What do you ask?"},{"t":"Me too, I'm French!","scenario":"Someone says they're French, and so are you! How do you react?"},{"t":"What's the name of the city?"},{"t":"I love France."},{"t":"Brazil is very big."},{"t":"The country is magnificent."}],"dialogue":{"title":"First meeting","lines":["Hello, what's your name?","My name is Léo. And you?","I'm Ana. Are you French?","Yes, I'm French. And you, are you Brazilian?","Yes, I'm Brazilian!"]},"concepts":{"tu-vs-vous":[{"title":"\"Tu\" or \"vous\"?","body":"<strong>Tu</strong> is informal — used with friends, family and people your own age. <strong>Vous</strong> is formal (used with strangers, superiors, older people) and is also the plural \"you\". When in doubt, always start with <strong>vous</strong> — it's safer than sounding too familiar.","examples":["you (informal)","you (formal or plural)"]}],"tu-es-contraction":[{"title":"\"Tu es\" becomes \"t'es\" in speech","body":"It would be \"Tu es français ?\", but in fast speech almost nobody pronounces the two words separately — <strong>tu es</strong> becomes <strong>t'es</strong>. It's so common that it even shows up in informal written messages: \"T'es français ?\". In the exercises here, keep writing the standard form <strong>tu es</strong> — the contraction is just for recognizing it when you hear or read it.","examples":["are you French? (fast speech)"]}],"comment-tappelles-wh-in-situ":[{"title":"\"Comment tu t'appelles ?\" also becomes \"Tu t'appelles comment ?\"","body":"In everyday speech it's just as common, or even more so, to leave the question word (\"comment\") at the END of the sentence, keeping the normal subject-verb order — <strong>tu t'appelles comment ?</strong> instead of \"comment tu t'appelles ?\". In the exercises here, keep using the order with \"comment\" at the start — it's the form both exercises here ask for.","examples":["what's your name? (everyday speech)"]}]},"trueFalse":[{"claim":"This question is used to find out someone's age.","whyNote":"Wrong — <strong>comment tu t'appelles ?</strong> asks for the NAME (appeler = to be called), not the age. For age you'd say \"quel âge as-tu ?\"."}]},"A1-20":{"title":"Past time expressions","goal":"Learn time markers for talking about the past, as preparation for the passé composé.","lessons":{"ontem-anteontem-semana-passada":"Yesterday, the day before yesterday and last week","fim-de-semana-mes-ano-passados":"Last weekend, last month and last year","dois-dias-atras-ja-recentemente":"Two days ago, this morning, already and recently","checkpoint":"Checkpoint"},"vocab":["yesterday","the day before yesterday","last week","last weekend","last month","last year","two days ago","this morning","already / ever","recently"],"phrases":[{"t":"Yesterday, I visited a museum.","scenario":"Someone asks what you did yesterday, and you visited a museum. What do you answer?"},{"t":"Last week, I ate at a restaurant.","scenario":"Someone asks what you did that was special last week — you ate at a restaurant. What do you say?"},{"t":"Last weekend, it rained.","scenario":"Someone asks what the weather was like last weekend — it rained a lot. What do you answer?"},{"t":"Have you ever visited Paris?","scenario":"You want to know whether a friend has ever been to Paris. What do you ask?"},{"t":"The day before yesterday, I visited Paris."},{"t":"Last month, I traveled to France."},{"t":"Last year, I learned French."},{"t":"Two days ago, it rained."},{"t":"This morning, I had a coffee."},{"t":"Recently, I changed jobs."}],"dialogue":{"title":"What did you do yesterday?","lines":["What did you do yesterday?","I worked in the morning, and in the afternoon I played sports.","And last weekend?","We went to the movies with friends."]},"concepts":{"hier-vs-semaine-derniere":[{"title":"\"Hier\" or \"la semaine dernière\"?","body":"<strong>Hier</strong> points to a specific day (yesterday). <strong>La semaine/le week-end dernier(-ère)</strong> points to a wider period (last week or last weekend). They all go well with the passé composé you've already seen: <strong>hier, j'ai visité</strong> un musée / <strong>la semaine dernière, j'ai mangé</strong> au restaurant.","examples":["yesterday","last week"]}],"quest-ce-que-tu-as-fait-wh-in-situ":[{"title":"\"Qu'est-ce que tu as fait hier ?\" also becomes \"T'as fait quoi hier ?\"","body":"In very everyday speech, this question often comes out like this: <strong>t'as fait quoi hier ?</strong> — \"qu'est-ce que\" disappears, \"quoi\" moves to the end, and \"tu as\" contracts to \"t'as\". Three simplifications at once, all very common together. In the exercises here, keep using the full form — it's the one the exercises ask for.","examples":["what did you do yesterday? (very everyday speech)"]}]},"trueFalse":[]},"A1-3":{"title":"Numbers and age","goal":"Count from zero to one hundred and say or ask someone's age.","lessons":{"primeiros-numeros":"First numbers","contar-ate-vinte":"Counting to twenty","idade":"Asking and saying your age","checkpoint":"Checkpoint"},"vocab":["zero","one (m. / f.)","two","three","ten","twenty","age","to have","years (old)","how much / how many"],"phrases":[{"t":"How old are you?","scenario":"You want to know a new friend's age. What do you ask?"},{"t":"I'm twenty years old.","scenario":"Someone asks your age and you're twenty. What do you answer?"},{"t":"He's ten years old.","scenario":"You're introducing your ten-year-old nephew. What do you say about his age?"},{"t":"There are ten of us.","scenario":"The waiter asks how many people are in your group, which has ten people. What do you say?"},{"t":"How much does it cost?"},{"t":"It's zero degrees outside."},{"t":"I have two brothers and three sisters."},{"t":"How old is your father?"}],"dialogue":{"title":"At the park","lines":["How old is your daughter?","She's eight. And your son?","He's ten.","They're so big!"]},"concepts":{"avoir-age":[{"title":"\"J'ai vingt ans\" — why \"ai\" and not \"suis\"?","body":"In English we say \"I <strong>am</strong> twenty\" or \"I'm <strong>twenty years old</strong>\", but in French age always uses the verb <strong>avoir</strong> (to have): <strong>j'ai</strong> vingt ans, never \"je suis vingt ans\". It's a common mistake for people who translate directly from English — it's worth memorizing this structure.","examples":["to have","age"]}],"vingt-to-quatrevingts":[{"title":"\"Vingt\" is the base of an odd system","body":"In France, after 69 the numbers jump to a base of 20: 70 is <strong>soixante-dix</strong> (\"sixty-ten\"), 80 is <strong>quatre-vingts</strong> (\"four-twenties\") — the \"vingt\" you just learned, multiplied! But it isn't like this everywhere French is spoken.","examples":[],"variants":["France","Belgium and Switzerland","Switzerland (only there)"]}],"quel-age-wh-in-situ":[{"title":"\"Quel âge as-tu ?\" also becomes \"T'as quel âge ?\"","body":"In everyday speech, \"tu as\" often shrinks to <strong>t'as</strong>, and the question word (\"quel âge\") can go at the end of the sentence — <strong>t'as quel âge ?</strong> instead of \"quel âge as-tu ?\". In the exercises here, keep using the form \"quel âge as-tu ?\" — it's the form the exercises ask for.","examples":["how old are you? (everyday speech)"]}]},"trueFalse":[]},"A1-4":{"title":"Family","goal":"Introduce family members and say how many siblings you have.","lessons":{"nuclear":"Immediate family","irmaos":"Talking about siblings","completa":"Extended family","checkpoint":"Checkpoint"},"vocab":["family","father","mother","brother","sister","parents","son","daughter","husband","wife / woman"],"phrases":[{"t":"This is my family.","scenario":"You're showing a photo and want to introduce your family. What do you say?"},{"t":"I have two brothers.","scenario":"Someone asks if you have siblings, and you have two brothers. What do you answer?"},{"t":"My father's name is Marc.","scenario":"You're telling someone your father's name, which is Marc. What do you say?"},{"t":"She's my sister.","scenario":"Someone asks who that girl in the photo is — she's your sister. What do you answer?"},{"t":"Family is very important."},{"t":"The father works in the city."},{"t":"The mother is making dinner."},{"t":"The brother and sister play together."},{"t":"The parents adore their children."},{"t":"The son and daughter like school."},{"t":"The husband and wife live in Paris."}],"dialogue":{"title":"Talking about family","lines":["Do you have any brothers or sisters?","Yes, I have a sister. And you?","I have a brother. His name is Paul.","How old is he?","He's fifteen."]},"concepts":{"mon-vs-ma":[{"title":"\"Mon frère\" or \"ma sœur\"?","body":"In French, the possessive agrees with the gender of the word that follows, not with the owner: <strong>mon</strong> père, <strong>mon</strong> frère (masculine), but <strong>ma</strong> mère, <strong>ma</strong> sœur (feminine) — even if you're the one speaking (man or woman). Who owns the thing doesn't matter for choosing mon/ma, only the gender of the word.","examples":["my brother","my sister"]}],"pere-mere-papa-maman":[{"title":"\"Le père\"/\"la mère\" in everyday life become \"papa\"/\"maman\"","body":"To talk ABOUT fathers/mothers in general, or in a more neutral way, you use <strong>le père</strong>/<strong>la mère</strong>. But when talking directly TO your own father/mother, or about your own family day to day, the normal words are <strong>papa</strong>/<strong>maman</strong> — even among adults.","examples":["dad (familiar use)","mom (familiar use)"]}],"repas-dominical":[{"title":"Sunday lunch with the family","body":"In France, it's traditional for the family to get together for a <strong>repas dominical</strong> — Sunday lunch — which is usually longer and more elaborate than meals during the rest of the week, with several courses (starter, main dish, cheese, dessert). It's one of the times when several generations of the family come together.","examples":["Sunday family lunch"]}]},"trueFalse":[]},"A1-5":{"title":"Food and drink","goal":"Order food and drink at a café or restaurant, and say what you like or don't like to eat.","lessons":{"pao-agua-cafe":"Ordering bread, water and coffee","leite-queijo-maca":"Talking about milk, cheese and apples","comer-beber-detestar":"Eating, drinking and saying what you hate","checkpoint":"Checkpoint"},"vocab":["bread","water","coffee","milk","cheese","apple","fish","to eat","to drink","to hate / to detest"],"phrases":[{"t":"I eat bread in the morning.","scenario":"Someone asks what you eat in the morning. What do you answer?"},{"t":"I like cheese, but I hate fish.","scenario":"You want to say you like cheese but really don't like fish. What do you say?"},{"t":"Do you drink coffee or milk?","scenario":"You're serving breakfast to a friend and want to know what they drink. What do you ask?"},{"t":"The check, please.","scenario":"You've finished eating at the restaurant and want to ask for the check. What do you say to the waiter?"},{"t":"The bread is delicious."},{"t":"I'd like some water, please."},{"t":"The coffee is very hot."},{"t":"The milk is in the fridge."},{"t":"The apple is red and sweet."},{"t":"I like eating in the morning."},{"t":"Do you want something to drink?"},{"t":"I think I'm going to hate this dish."}],"dialogue":{"title":"At the café","lines":["Hello, what would you like?","A coffee and a croissant, please.","Anything else?","No thanks, that's all.","Here you go, that's five euros."]},"concepts":{"aime-le-vs-bois-du":[{"title":"\"J'aime LE café\" or \"je bois DU café\"?","body":"With verbs of liking (<strong>aimer</strong>, détester), you use the definite article to talk about the thing in general: <strong>j'aime le café</strong> (I like coffee, in general). But when you're talking about an amount — drinking, eating, buying — you use the partitive article: <strong>je bois du café</strong> (I drink [some] coffee). It's a distinction English doesn't make, but it's essential in French.","examples":["to drink","to hate / to detest"]}],"croissant-nao-e-diario":[{"title":"Croissants every day? Not for most French people","body":"There's an idea that French people eat croissants for breakfast every day — but in practice it's more common to save croissants for weekends or special occasions. Day to day, French breakfast is usually simpler: bread with butter/jam (tartine), or just coffee.","examples":["bread with butter/jam — the most common breakfast"]}]},"trueFalse":[{"claim":"We say this to ask for the check in a restaurant.","whyNote":"Correct — <strong>l'addition</strong> is \"the check\" in French; this phrase is exactly how you ask for the check in a restaurant."}]},"A1-6":{"title":"Time and daily routine","goal":"Tell the time and describe your daily routine.","lessons":{"horas-e-periodos":"Telling the time and parts of the day","noite-acordar-levantar":"Night, waking up and getting up","rotina-diaria":"Eating, working, sleeping and midnight","checkpoint":"Checkpoint"},"vocab":["time / hour","morning","noon","evening (in the evening)","to wake up","to get up","to eat","to work","to sleep","midnight"],"phrases":[{"t":"What time is it?","scenario":"You forgot your watch and want to know what time it is. What do you ask?"},{"t":"It's eight o'clock.","scenario":"Someone asks the time and it's eight o'clock. What do you answer?"},{"t":"I wake up at seven o'clock.","scenario":"Someone asks what time you wake up every day. What do you answer?"},{"t":"In the evening, I watch TV.","scenario":"Someone asks what you do in the evening. What do you answer?"},{"t":"He's checking the time on his phone."},{"t":"At noon, I eat at home."},{"t":"He's going to wake up early tomorrow."},{"t":"She's going to get up at seven o'clock."},{"t":"He has to work until midnight."},{"t":"I'm going to sleep now."}],"dialogue":{"title":"My routine","lines":["What time do you get up?","I get up at six thirty.","And when do you work?","I work in the morning and in the afternoon."]},"concepts":{"etre-heures":[{"title":"\"Il est huit heures\" — again, no \"avoir\"... or rather, just \"être\"!","body":"Unlike age (which uses avoir), telling the time in French uses the verb <strong>être</strong>: <strong>il est</strong> huit heures (it's eight o'clock). Notice that here the \"il\" doesn't refer to anyone — it's an impersonal \"il\", just there to build the sentence, like the \"it\" in \"it's raining\" in English.","examples":["time / hour"]}],"le-midi-almoco-longo":[{"title":"\"Le midi\" in France is time to sit down and really eat","body":"In France, lunch (<strong>le déjeuner</strong>, from around noon to 1 p.m.) is usually a real break — many restaurants and work canteens serve a full meal (starter, main course, sometimes dessert), and it's common to set aside 45 minutes to an hour just for it, rather than eating quickly at your desk.","examples":["lunch"]}]},"trueFalse":[]},"A1-7":{"title":"Days and months","goal":"Say the days of the week and the months, and arrange to meet someone.","lessons":{"dias-da-semana":"Days of the week and today","ontem-amanha-semana":"Tomorrow, yesterday and the week","meses-e-data":"Months and the date","checkpoint":"Checkpoint"},"vocab":["Monday","Tuesday","today","tomorrow","yesterday","the week","the month","January","December","the date"],"phrases":[{"t":"What day is it today?","scenario":"You've lost track of the day of the week. What do you ask?"},{"t":"Today is Monday.","scenario":"Someone asks what day it is, and it's Monday. What do you answer?"},{"t":"My birthday is in March.","scenario":"Someone asks which month your birthday is in — March. What do you say?"},{"t":"See you tomorrow!","scenario":"You're saying goodbye to a coworker and you'll see them again tomorrow. What do you say?"},{"t":"Today the weather is nice."},{"t":"Next week, I'm going on a trip."},{"t":"The month of January is very cold."},{"t":"My birthday is in December."},{"t":"What's the date today?"}],"dialogue":{"title":"Arranging to meet","lines":["What day shall we meet?","Tuesday, does that work for you?","No, I work on Tuesday. What about Wednesday?","Perfect, see you Wednesday then!"]},"concepts":{"a-demain-vs-a-bientot":[{"title":"\"À demain\" or \"à bientôt\"?","body":"French goodbyes vary depending on how long until you meet again: <strong>à demain</strong> when you know you'll see the person tomorrow, and <strong>à bientôt</strong> when the reunion is more uncertain, just \"see you soon\". <strong>Au revoir</strong>, on the other hand, is neutral and works for any goodbye, without saying when the next meeting will be.","examples":["tomorrow","yesterday"]}],"dias-semana-deuses-romanos":[{"title":"Where do the names of the days of the week come from?","body":"The French days of the week come from Roman gods/planets: <strong>lundi</strong> is the day of the Moon (Lune), <strong>mardi</strong> is the day of Mars (Mars). The pattern continues: mercredi (Mercury), jeudi (Jupiter), vendredi (Venus), samedi (Saturn) — only dimanche breaks the rule, coming from the Latin for \"the Lord's day\".","examples":["Monday — day of the Moon","Tuesday — day of Mars"]}],"nous-sommes-on-est":[{"title":"\"Nous sommes lundi\" becomes \"On est lundi\" in everyday speech","body":"In everyday speech, <strong>on</strong> has practically replaced <strong>nous</strong> as \"we\" — <strong>on est</strong> lundi instead of \"nous sommes lundi\". The verb conjugates like \"il/elle\" (on est, on a, on va), not like \"nous\". In the exercises here, keep using \"nous\" — it's the form the exercises ask for.","examples":["it's Monday (everyday speech)"]}]},"trueFalse":[]},"A1-8":{"title":"Places and directions","goal":"Ask for and give directions to a place in the city.","lessons":{"lugares-na-cidade":"Places in the city","hospital-estacao-em-frente":"Hospital, station and straight ahead","direcoes":"Giving directions: left, right, near and far","checkpoint":"Checkpoint"},"vocab":["the street","the square","the museum","the hospital","the (train) station","straight ahead","to the left","to the right","near","far"],"phrases":[{"t":"Where is the station?","scenario":"You're lost and need to find the train station. What do you ask someone on the street?"},{"t":"Turn left.","scenario":"You're giving someone directions and need to tell them to turn left. What do you say?"},{"t":"It's straight ahead.","scenario":"Someone asks how to get to a place that's straight ahead. What do you answer?"},{"t":"Is it far from here?","scenario":"You want to know whether the place you're looking for is far from where you are. What do you ask?"},{"t":"The street is very quiet at night."},{"t":"The square is in the city center."},{"t":"The hospital is far from here."}],"dialogue":{"title":"Asking for information","lines":["Excuse me, where is the museum?","Straight ahead, then to the right.","Is it far?","No, it's five minutes away.","Thank you very much!"]},"concepts":{"ou-est-vs-il-y-a":[{"title":"\"Où est...?\" or \"Il y a...?\"","body":"Use <strong>où est...?</strong> when you already know the place exists and just want to know where it is (e.g. où est la gare? — where is the station?). Use <strong>il y a...?</strong> when you don't know whether the place exists nearby (e.g. il y a une pharmacie près d'ici? — is there a pharmacy near here?).","examples":[]}]},"trueFalse":[{"claim":"This question is about the price of something.","whyNote":"Wrong — <strong>c'est loin d'ici ?</strong> asks about DISTANCE (loin = far), not price. For price you'd say \"c'est combien ?\"."}]},"A1-9":{"title":"Nationalities","goal":"Say your nationality and other people's nationality, masculine and feminine.","lessons":{"nacionalidades-1":"French, Brazilian and American","nacionalidades-2":"English, Spanish and Italian","nacionalidade-e-origem":"German, Portuguese and asking where someone is from","checkpoint":"Checkpoint"},"vocab":["French (m.) / French (f.)","Brazilian (m.) / Brazilian (f.)","American (m.) / American (f.)","English (m.) / English (f.)","Spanish (m.) / Spanish (f.)","Italian (m.) / Italian (f.)","German (m.) / German (f.)","Portuguese (m.) / Portuguese (f.)","nationality","to come from (a place)"],"phrases":[{"t":"I'm Brazilian.","scenario":"Someone asks your nationality in a job interview. What do you say?"},{"t":"He is French, she is Spanish.","scenario":"You're introducing two friends of different nationalities — a Frenchman and a Spanish woman. What do you say about them?"},{"t":"Where do you come from?","scenario":"You've met someone new on a trip and want to know where they come from. What do you ask?"},{"t":"I come from Portugal.","scenario":"Someone asks where you come from, and you come from Portugal. What do you answer?"},{"t":"Nationality is written on the passport."}],"dialogue":{"title":"Where are you from?","lines":["Where are you from?","I'm Italian, and you?","Me, I'm German.","Do you live in Germany?","No, I live in Portugal now."]},"concepts":{"etre-nationalite-vs-venir-de":[{"title":"\"Je suis brésilienne\" or \"je viens du Brésil\"?","body":"<strong>Être + nationality</strong> talks about your identity (je suis brésilienne). <strong>Venir de + country</strong> talks about your origin / where you come from (je viens du Brésil). The two sentences say almost the same thing, but notice the preposition: <strong>du</strong> Brésil, <strong>de</strong> France, <strong>d'</strong>Espagne — it changes depending on the gender and the first letter of the country's name.","examples":["to come from (a place)","nationality"]}],"dou-viens-tu-wh-in-situ":[{"title":"\"D'où viens-tu ?\" also becomes \"Tu es d'où ?\"","body":"Notice that the dialogue you just read already uses the everyday form: <strong>Tu es d'où ?</strong> instead of \"D'où viens-tu ?\". In everyday speech, it's common to keep the normal subject-verb order and move the question word to the end. In the exercises here, keep using \"D'où viens-tu ?\" — it's the form the exercises ask for.","examples":["where are you from? (everyday speech)"]}]},"trueFalse":[{"claim":"This question is used to find out someone's name.","whyNote":"Wrong — <strong>d'où viens-tu ?</strong> asks where the person comes FROM (viens = come), not their name. For a name you'd say \"comment tu t'appelles ?\"."}]},"A1-g1":{"title":"The verbs avoir and être","goal":"Conjugate avoir and être in the present tense and recognize how they are used in sentences.","grammar":{"blocks":[{"title":"Avoir and être","body":"Avoir (to have) and être (to be) are the two most-used verbs in French — and the only ones that are completely irregular in the present tense. You've already seen several of their forms in the last few units (je suis, j'ai, il a...) without stopping to think about the full conjugation.","examples":["I am Brazilian. (être)","I am twenty years old. (avoir)"]},{"title":"No pattern to work out","body":"Notice that neither conjugation follows a regular pattern — you can't \"work out\" the form from the infinitive, so it's worth memorizing the whole table, not just the isolated forms you've already seen.","examples":["He is ten years old. (avoir)","She is my sister. (être)"]},{"title":"A common trap","body":"French uses avoir (to have) in several expressions where English uses \"to be\" — avoir faim (to be hungry), avoir soif (to be thirsty), avoir peur (to be afraid), avoir raison (to be right). If the English sentence uses \"to be\" with a feeling or state like these, chances are French uses avoir.","examples":["I am hungry.","She is right."]},{"title":"Très bien! 🎉","body":"Être also works as an auxiliary verb in other tenses you'll see in A2 — the foundation you're building now will make that much easier later on. Here is the full conjugation of both verbs before you practice:","examples":[],"table":[{"label":"être","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]},{"label":"avoir","pronouns":["je (j')","tu","il / elle / on","nous","vous","ils / elles"]}]}],"exercises":[{"hint":"être"},{"hint":"avoir"},{"hint":"être"},{"hint":"avoir"},{"hint":"être"},{"hint":"avoir"}]}},"A1-g10":{"title":"Numbers from 70 to 99","goal":"Understand and correctly form the numbers from seventy to ninety-nine.","grammar":{"blocks":[{"title":"Up to sixty, it is regular","body":"Trente (30), quarante (40), cinquante (50) and soixante (60) follow the normal pattern, one word for each ten — just like in English. The trouble starts after sixty: unlike English, standard French simply has no word of its own for seventy, eighty or ninety.","examples":["I am thirty years old.","It costs sixty euros."]},{"title":"70 = 60 + 10","body":"Seventy (soixante-dix) is literally \"sixty-ten\". From 71 to 79, you keep adding to sixty: soixante et onze (71), soixante-douze (72)... up to soixante-dix-neuf (79).","examples":["He is seventy years old. (60+10)","That makes seventy-five euros. (60+15)"]},{"title":"80 = 4 × 20","body":"Eighty (quatre-vingts) is \"four twenties\". From 81 to 89, you add on without \"et\": quatre-vingt-un (81), quatre-vingt-deux (82)... The \"s\" of vingts disappears as soon as another number follows.","examples":["She is eighty years old. (4×20)","There are eighty-three people. (4×20+3)"]},{"title":"90 = 4 × 20 + 10","body":"Ninety (quatre-vingt-dix) combines the two rules: four twenties, plus ten. From 91 to 99, same logic as 80: quatre-vingt-onze (91)... quatre-vingt-dix-neuf (99).","examples":["My grandfather is ninety years old. (4×20+10)","It costs ninety-nine euros. (4×20+19)"]},{"title":"Très bien! 🎉","body":"To sum up the logic of the tens from 70 to 90 — the secret is remembering that soixante-dix and quatre-vingt-dix are the base for adding again:","examples":[],"table":[{"label":"Tens","pronouns":["70","71","80","81","90","91","99"]}]}],"exercises":[{"prompt":"70 in French:","hint":"60 + 10"},{"prompt":"71 in French:","hint":"60 + 11 (with et)"},{"prompt":"80 in French:","hint":"4 × 20"},{"prompt":"81 in French:","hint":"4×20 + 1 (no et)"},{"prompt":"90 in French:","hint":"4×20 + 10"},{"prompt":"99 in French:","hint":"4×20 + 19"}]}},"A1-g2":{"title":"Possessive adjectives","goal":"Use mon/ma/mes, ton/ta/tes, son/sa/ses and the other possessive adjectives correctly.","grammar":{"blocks":[{"title":"My, our, your...","body":"In French, the possessive adjective agrees with the gender and number of the thing owned — not with the owner! That is why \"my\" can be mon, ma or mes depending on the word that follows. (English does the opposite: his/her depends on the owner.)","examples":["This is my brother. (frère is masculine)","This is my sister. (sœur is feminine)"]},{"title":"Our, your (plural), their...","body":"Notre/votre/leur (our, your (plural/formal), their), on the other hand, do not change with gender — they just get an \"s\" in the plural (nos/vos/leurs) whenever the thing owned is plural.","examples":["Our father is called Jean.","These are their parents."]},{"title":"A sound-based exception","body":"Before a feminine word that starts with a vowel (or a silent \"h\"), mon/ton/son are used instead of ma/ta/sa — just to avoid an awkward clash of two vowel sounds in a row. The word is still feminine; only the written form changes.","examples":["This is my friend Sophie. (amie is feminine, but starts with a vowel)","Her school is far away."]},{"title":"Très bien! 🎉","body":"Here is the complete table of possessives — organized by the gender/number of the thing owned, not by who the owner is:","examples":[],"table":[{"label":"Masculine singular","pronouns":["my","your (informal)","his / her / its","our","your (plural / formal)","their"]},{"label":"Feminine singular","pronouns":["my","your (informal)","his / her / its","our","your (plural / formal)","their"]},{"label":"Plural (m/f)","pronouns":["my (plural)","your (informal, plural)","his / her / its (plural)","our (plural)","your (plural / formal, plural)","their (plural)"]}]}],"exercises":[{"hint":"my (masc.)"},{"hint":"my (fem.)"},{"hint":"my (plural)"},{"hint":"our"},{"hint":"their (plural)"},{"hint":"my — but amie starts with a vowel"}]}},"A1-g3":{"title":"First-group verbs and pronominal verbs","goal":"Conjugate regular -er verbs and pronominal (reflexive) verbs in the present tense.","grammar":{"blocks":[{"title":"First-group verbs (-er)","body":"Most French verbs end in -er in the infinitive — this is the so-called \"first group\", and it is the most regular of all. Just drop the -er and add the endings -e, -es, -e, -ons, -ez, -ent.","examples":["I work in the morning.","You eat at noon."]},{"title":"A small exception: manger","body":"Verbs ending in -ger (like manger) get an extra \"e\" before -ons, just to keep the soft \"g\" sound — it is the only change, and it only happens with \"nous\".","examples":["We eat at seven o'clock.","You (plural) eat bread."]},{"title":"Pronominal verbs","body":"Some verbs always come with a pronoun that \"reflects\" back to the subject — se réveiller (to wake up), se lever (to get up). The pronoun changes along with the subject: me, te, se, nous, vous, se.","examples":["I get up at six o'clock.","Do you wake up early?"]},{"title":"Très bien! 🎉","body":"Notice that a pronominal verb is conjugated exactly like an ordinary first-group verb — only the reflexive pronoun in front changes. Here is the full conjugation of both models:","examples":[],"table":[{"label":"travailler","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]},{"label":"se lever","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]}]}],"exercises":[{"hint":"se réveiller"},{"hint":"se lever"},{"hint":"manger"},{"hint":"travailler"},{"hint":"aimer"},{"hint":"se lever"}]}},"A1-g4":{"title":"Prepositions with countries and cities","goal":"Use à, en, au and aux correctly with the names of cities and countries.","grammar":{"blocks":[{"title":"à + city","body":"To say that something happens in a city, you always use à — with no article before the city name, and no need to worry about gender.","examples":["I live in Paris.","She is traveling to Tokyo."]},{"title":"en + feminine country / au + masculine country","body":"Most countries whose name ends in -e are feminine and use en. The others (masculine) use au.","examples":["I am going to France. (la France, feminine)","He works in Brazil. (le Brésil, masculine)"]},{"title":"aux + plural country","body":"Some countries have a plural name — like les États-Unis (the United States). In that case, the preposition becomes aux.","examples":["They live in the United States.","She is in the Netherlands."]},{"title":"Très bien! 🎉","body":"To sum up: a city always takes à; a country depends on its gender (en/au) or on being plural (aux). Here is a table with a few examples:","examples":[],"table":[{"label":"Prepositions","pronouns":["city","feminine country (most)","masculine country","plural country"]},{"label":"Examples","pronouns":["la France (fem.)","le Brésil (masc.)","le Portugal (masc.)","les États-Unis (plural)"]}]}],"exercises":[{"hint":"city"},{"hint":"masculine country"},{"hint":"feminine country"},{"hint":"plural country"},{"hint":"city"},{"hint":"masculine country"}]}},"A1-g5":{"title":"The verbs faire and prendre","goal":"Conjugate the irregular verbs faire and prendre in the present tense.","grammar":{"blocks":[{"title":"Faire: a verb with a thousand uses","body":"Faire (to do / to make) is irregular and shows up in lots of fixed expressions — including the weather ones you've already seen, like il fait chaud and il fait froid.","examples":["It's 30 degrees today.","What are you doing tonight?"]},{"title":"Prendre: to take, to catch, to have","body":"Prendre (to take / to catch) is used both for transportation, as you've already seen, and for ordering food or drink — it's a very versatile everyday verb.","examples":["I often take the metro.","Are you having a coffee?"]},{"title":"A similar pattern","body":"Notice that both verbs change their stem in the plural — faire goes from fais-/fais-/fait- in the singular to faisons/faites/font in the plural, and prendre doubles the \"n\" in ils/elles prennent. These irregularities are worth paying attention to.","examples":["We take the bus together.","What are you all doing this weekend?"]},{"title":"Très bien! 🎉","body":"Here is the full conjugation of both verbs — notice the highlighted irregularities:","examples":[],"table":[{"label":"faire","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]},{"label":"prendre","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]}]}],"exercises":[{"hint":"faire"},{"hint":"prendre"},{"hint":"faire"},{"hint":"prendre"},{"hint":"prendre"},{"hint":"faire"}]}},"A1-g6":{"title":"Modal verbs and il faut","goal":"Conjugate vouloir, pouvoir, devoir and savoir, and understand when to use il faut instead of devoir.","grammar":{"blocks":[{"title":"Vouloir and pouvoir","body":"Vouloir (to want) and pouvoir (can / to be able to) are two of the most used verbs in French, and they appear in almost every everyday conversation. You've already seen both in earlier units, without stopping to think about the full conjugation.","examples":["Do you want a dessert?","Can I try on this dress?"]},{"title":"Devoir and savoir","body":"Devoir (must / to have to) expresses personal obligation, and savoir (to know) expresses knowledge or a learned skill — different from connaître (to be familiar with a place/person), which you'll see later on.","examples":["You need to rest.","I know how to speak French."]},{"title":"Il faut: an impersonal alternative to devoir","body":"Il faut + infinitive expresses a need or a general rule — without saying WHO has to do something. Il faut never conjugates; it's always the same form. Devoir + infinitive, on the other hand, is personal: you conjugate the verb to say that ONE specific person has to do something (je dois, tu dois, il doit...). Compare the two examples: the first is a general rule, the second is aimed at a specific person.","examples":["You have to sleep eight hours. (general rule, applies to anyone)","You need to rest. (directed at you specifically)"]},{"title":"Très bien! 🎉","body":"Four essential verbs — all irregular, so it's worth memorizing the whole table. Remember: il faut isn't in the table because it doesn't conjugate; it's always invariable.","examples":[],"table":[{"label":"vouloir","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]},{"label":"pouvoir","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]},{"label":"devoir","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]},{"label":"savoir","pronouns":["je","tu","il / elle / on","nous","vous","ils / elles"]}]}],"exercises":[{"hint":"vouloir"},{"hint":"pouvoir"},{"hint":"devoir"},{"hint":"savoir"},{"hint":"il faut (impersonal)"},{"hint":"vouloir"},{"hint":"pouvoir"},{"hint":"savoir"}]}},"A1-g7":{"title":"Comparatives","goal":"Compare people and things using plus, moins and aussi... que.","grammar":{"blocks":[{"title":"Plus... que (more... than)","body":"To say that something has \"more\" of a quality than something else, you use plus + adjective + que. It's the most common comparison structure in French.","examples":["My brother is taller than me.","This dress is prettier than the other one."]},{"title":"Moins... que / aussi... que","body":"On the other side, moins... que expresses inferiority (\"less... than\") and aussi... que expresses equality (\"as... as\"). The structure is always the same; only the little word in the middle changes.","examples":["She is less tall than him.","He is as kind as his brother."]},{"title":"An irregularity: bon → meilleur","body":"Just like in English \"good\" doesn't become \"more good\" but \"better\", in French bon also breaks the pattern: there is no \"plus bon\" — the correct form is meilleur. The same happens with the adverb bien (well), which becomes mieux (better) in the comparative.","examples":["This cake is better than the other one.","She sings better than me."]},{"title":"Très bien! 🎉","body":"Recapping the three comparison structures and the bon/bien exception — it's worth memorizing this table, because bon → meilleur is a very common mistake among beginners:","examples":[],"table":[{"label":"Comparatives","pronouns":["superiority (more... than)","inferiority (less... than)","equality (as... as)","bon (good) → irregular","bien (well) → irregular"]}]}],"exercises":[{"hint":"superiority"},{"hint":"inferiority"},{"hint":"equality"},{"hint":"bon → irregular"},{"hint":"equality"},{"hint":"inferiority"}]}},"A1-g8":{"title":"Adverbs of frequency","goal":"Use toujours, souvent, parfois, rarement and jamais to say how often you do something.","grammar":{"blocks":[{"title":"Adverbs of frequency","body":"From most to least frequent: toujours (always), souvent (often), parfois (sometimes), rarement (rarely) and jamais (never). In French, the adverb usually comes right after the conjugated verb — unlike English, where it usually goes before the verb.","examples":["I always read in the evening.","She sometimes plays the guitar."]},{"title":"Where to put the adverb","body":"Placing it right after the verb works for any everyday verb — including the leisure verbs you just learned.","examples":["We often go out on the weekend.","He rarely sings."]},{"title":"Jamais needs ne","body":"Jamais (never) works as a negation — so it needs ne before the verb, just like in ne...pas. The full structure is ne...jamais.","examples":["I never dance.","He never goes out on Mondays."]},{"title":"Très bien! 🎉","body":"Here is the full scale, from most to least frequent — worth coming back to whenever you need to describe a habit:","examples":[],"table":[{"label":"Adverbs (most to least frequent)","pronouns":["always","often","sometimes","rarely","never (+ ne)"]}]}],"exercises":[{"hint":"always"},{"hint":"sometimes"},{"hint":"often"},{"hint":"never"},{"hint":"rarely"},{"hint":"always"}]}},"A1-g9":{"title":"The passé composé","goal":"Conjugate the passé composé with avoir and with être to talk about past actions.","grammar":{"blocks":[{"title":"Passé composé with avoir","body":"The passé composé is the most common tense for talking about the past in French. Most verbs form it with the present tense of avoir + the past participle. Regular -er verbs form the participle by changing -er to -é.","examples":["I ate at the restaurant.","She worked all day."]},{"title":"Some irregular participles","body":"Some very common verbs have an irregular participle that you have to memorize — like faire → fait and prendre → pris, two verbs you already know.","examples":["I did some sports yesterday.","He took the train."]},{"title":"Passé composé with être","body":"A small group of verbs (mainly verbs of movement, like aller) and ALL pronominal verbs use être as the auxiliary, not avoir. When the auxiliary is être, the participle agrees in gender and number with the subject — it gets an -e for feminine and an -s for plural.","examples":["She went to the market. (être + feminine agreement)","I got up early. (pronominal verb, always with être)"]},{"title":"Très bien! 🎉","body":"You've completed level A1! Here is a summary of the two auxiliaries — notice that most verbs use avoir, and être is reserved for movement and pronominal verbs:","examples":[],"table":[{"label":"With avoir (most verbs)","pronouns":["manger →","faire →","prendre →"]},{"label":"With être (movement + pronominals)","pronouns":["aller →","arriver →","se lever →"]}]}],"exercises":[{"hint":"avoir (manger)"},{"hint":"avoir (faire)"},{"hint":"avoir (prendre)"},{"hint":"avoir (travailler)"},{"hint":"être (aller)"},{"hint":"être (se lever)"},{"hint":"avoir (visiter)"},{"hint":"être (arriver)"}]}}}};
